mapper.select:
SELECT p.id as projectId, p.creator_id as creatorId, u.nickname as creatorNickname, p.category_id as categoryId, p.title, p.goal_amount as goalAmount, p.current_amount as currentAmount, p.end_at as endAt, p.status, p.created_at as createdAt FROM project p LEFT JOIN user u ON p.creator_id = u.id
AND p.status IN
#{status}
AND p.category_id IN
#{categoryId}
AND (p.created_at < #{cursorCreatedAt} OR (p.created_at = #{cursorCreatedAt} AND p.id < #{cursorId}))
ORDER BY p.created_at DESC, p.id DESC LIMIT #{limit}

mapper.update:
UPDATE project
SET title = #{title},
    content_blocks = #{contentBlocks}
WHERE id = #{projectId}

UPDATE project
SET status = #{status}
WHERE id = #{projectId}
